import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import { format } from 'date-fns';
import type { EmployeeReview } from '@/types/employee.types';
import { CRITERIA } from '../../data/configs.data';
import { parseReviewNotes } from './reviewNotesUtils';

type Props = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    review: EmployeeReview | null;
};

function formatCreatedAt(iso: string | undefined): string {
    if (!iso) return '—';
    try {
        return format(new Date(iso), 'yyyy-MM-dd');
    } catch {
        return iso;
    }
}

export default function ReviewViewDialog({ open, onOpenChange, review }: Props) {
    const parsed = review ? parseReviewNotes(review.notes) : {};
    const emp = review?.employee;

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent
                dir="rtl"
                className="max-w-[640px] max-h-[90vh] overflow-y-auto rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-4 border-[#E8E7EA]"
            >
                <DialogHeader>
                    <h2 className="text-xl font-bold text-primery-blue-500 text-start">تفاصيل التقييم</h2>
                    <div className="w-full border-b border-[#D1D1D1] mt-2" />
                </DialogHeader>

                {review ? (
                    <div className="space-y-4 text-start text-sm">
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            <div>
                                <p className="text-white-blue-600 font-medium">الموظف</p>
                                <p className="text-primery-blue-900 mt-1">{emp?.name ?? '—'}</p>
                            </div>
                            <div>
                                <p className="text-white-blue-600 font-medium">تاريخ التقييم</p>
                                <p className="text-primery-blue-900 mt-1">{formatCreatedAt(review.created_at)}</p>
                            </div>
                            <div>
                                <p className="text-white-blue-600 font-medium">متوسط التقييم</p>
                                <p className="text-primery-blue-900 mt-1 tabular-nums">
                                    {review.rating != null ? `${review.rating} / 5` : '—'}
                                </p>
                            </div>
                            <div>
                                <p className="text-white-blue-600 font-medium">المقيم</p>
                                <p className="text-primery-blue-900 mt-1">{review.reviewer_name ?? '—'}</p>
                            </div>
                            {parsed.period ? (
                                <div className="sm:col-span-2">
                                    <p className="text-white-blue-600 font-medium">الفترة التقييمية</p>
                                    <p className="text-primery-blue-900 mt-1">{parsed.period}</p>
                                </div>
                            ) : null}
                        </div>

                        {parsed.criteria && CRITERIA.some((c) => typeof parsed.criteria?.[c.name] === 'number') ? (
                            <div>
                                <p className="text-white-blue-600 font-medium mb-2">المعايير</p>
                                <ul className="space-y-1 border border-[#E8E7EA] rounded-lg p-3 bg-white">
                                    {CRITERIA.map((c) => {
                                        const v = parsed.criteria?.[c.name];
                                        if (typeof v !== 'number') return null;
                                        return (
                                            <li key={c.name} className="flex justify-between gap-4 text-[#625E74]">
                                                <span>{c.label}</span>
                                                <span className="tabular-nums font-medium text-primery-blue-900">
                                                    {v} / 5
                                                </span>
                                            </li>
                                        );
                                    })}
                                </ul>
                            </div>
                        ) : null}

                        {parsed.rawText && !parsed.criteria ? (
                            <div>
                                <p className="text-white-blue-600 font-medium mb-1">ملاحظات</p>
                                <p className="text-[#625E74] whitespace-pre-wrap rounded-lg border border-[#E8E7EA] p-3 bg-white">
                                    {parsed.rawText}
                                </p>
                            </div>
                        ) : null}

                        {parsed.strengths ? (
                            <div>
                                <p className="text-white-blue-600 font-medium mb-1">نقاط القوة</p>
                                <p className="text-[#625E74] whitespace-pre-wrap rounded-lg border border-[#E8E7EA] p-3 bg-white">
                                    {parsed.strengths}
                                </p>
                            </div>
                        ) : null}
                        {parsed.development ? (
                            <div>
                                <p className="text-white-blue-600 font-medium mb-1">مجالات التطوير</p>
                                <p className="text-[#625E74] whitespace-pre-wrap rounded-lg border border-[#E8E7EA] p-3 bg-white">
                                    {parsed.development}
                                </p>
                            </div>
                        ) : null}
                        {parsed.goals ? (
                            <div>
                                <p className="text-white-blue-600 font-medium mb-1">أهداف الفترة القادمة</p>
                                <p className="text-[#625E74] whitespace-pre-wrap rounded-lg border border-[#E8E7EA] p-3 bg-white">
                                    {parsed.goals}
                                </p>
                            </div>
                        ) : null}
                    </div>
                ) : null}
            </DialogContent>
        </Dialog>
    );
}
