import { useEffect, useMemo, useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Star } from 'lucide-react';
import { toast } from 'sonner';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import type { Employee, EmployeeReview } from '@/types/employee.types';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import CalendarIcon from '@/components/icons/CalendarIcon';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { cn } from '@/lib/utils';
import { AddEmployeeReviewFormValues, AddEmployeeReviewSchema } from './add-employee-schema';
import { AddEmployeeReviewDefaultValues, CRITERIA } from '../../data/configs.data';
import SearchableSelectInputForm from '@/components/forms/SearchableSelectInputForm';
import { parseReviewNotes } from './reviewNotesUtils';
import { useAppSelector } from '@/core/global-store';
import FileInput from '../../forms/addVacation/FileInput';

type Props = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSaved?: () => void;
    /** Edit existing review (same form + `review-update`) */
    reviewToEdit?: EmployeeReview | null;
};

function StarCriterion({ label, value, onChange }: { label: string; value: number; onChange: (v: number) => void }) {
    return (
        <div className="space-y-2">
            <p className="text-sm font-medium text-primery-blue-900 text-end">{label}</p>
            <div className="flex flex-row-reverse items-center justify-end gap-3 flex-wrap">
                <span className="text-sm text-[#625E74] tabular-nums whitespace-nowrap">
                    5 / {value === 0 ? '—' : value}
                </span>
                <div className="flex flex-row-reverse gap-0.5">
                    {[1, 2, 3, 4, 5].map((star) => (
                        <button
                            key={star}
                            type="button"
                            onClick={() => onChange(star === value ? 0 : star)}
                            className="p-0.5 rounded hover:opacity-90 focus:outline-none focus-visible:ring-2 focus-visible:ring-primery-blue-500"
                            aria-label={`${star} من 5`}
                        >
                            <Star
                                className={cn(
                                    'w-5 h-5 transition-colors',
                                    star <= value ? 'fill-amber-400 text-amber-400' : 'fill-transparent text-gray-300',
                                )}
                            />
                        </button>
                    ))}
                </div>
            </div>
        </div>
    );
}

export default function AddEmployeeReviewDialog({ open, onOpenChange, onSaved, reviewToEdit = null }: Props) {
    const user = useAppSelector((state) => state.auth.user);

    const [submitting, setSubmitting] = useState(false);
    const [employees, setEmployees] = useState<Employee[]>([]);
    const [employeesLoading, setEmployeesLoading] = useState(false);
    const periodOptions = useMemo(() => {
        const year = new Date().getFullYear();
        const make = (y: number) => [
            { value: `q1-${y}`, label: `الربع الأول ${y}` },
            { value: `q2-${y}`, label: `الربع الثاني ${y}` },
            { value: `q3-${y}`, label: `الربع الثالث ${y}` },
            { value: `q4-${y}`, label: `الربع الرابع ${y}` },
        ];
        // include current year + previous year for convenience
        return [...make(year), ...make(year - 1)];
    }, []);
    const form = useForm<AddEmployeeReviewFormValues>({
        resolver: zodResolver(AddEmployeeReviewSchema),
        defaultValues: AddEmployeeReviewDefaultValues,
    });

    useEffect(() => {
        if (!open) return;
        if (reviewToEdit) {
            const parsed = parseReviewNotes(reviewToEdit.notes);
            const c = parsed.criteria ?? {};
            const num = (v: unknown) => (typeof v === 'number' ? v : 0);
            form.reset({
                employee_id: String(reviewToEdit.employee_id),
                period: parsed.period ?? '',
                quality: num(c.quality),
                productivity: num(c.productivity),
                communication: num(c.communication),
                discipline: num(c.discipline),
                initiative: num(c.initiative),
                teamwork: num(c.teamwork),
                strengths: parsed.strengths ?? '',
                development: parsed.development ?? '',
                goals: parsed.goals ?? '',
            });
        } else {
            form.reset(AddEmployeeReviewDefaultValues);
        }
    }, [open, reviewToEdit, form]);

    useEffect(() => {
        if (!open) return;
        let cancelled = false;
        const run = async () => {
            setEmployeesLoading(true);
            try {
                const res = await apiGet({
                    endpoint: endpoints.employee.list,
                    queryParams: { pageSize: 200, page: 1 },
                });
                const rows = res.data?.data?.data;
                if (!cancelled) setEmployees(Array.isArray(rows) ? rows : []);
            } catch {
                if (!cancelled) setEmployees([]);
            } finally {
                if (!cancelled) setEmployeesLoading(false);
            }
        };
        run();
        return () => {
            cancelled = true;
        };
    }, [open]);

    const employeeOptions = useMemo(
        () =>
            employees.map((e) => ({
                name: e.name,
                value: String(e.id),
                description: `#${e.id}`,
            })),
        [employees],
    );

    const onSubmit = async (data: AddEmployeeReviewFormValues) => {
        setSubmitting(true);
        try {
            const scores = [
                data.quality,
                data.productivity,
                data.communication,
                data.discipline,
                data.initiative,
                data.teamwork,
            ];
            const rating = Math.round((scores.reduce((a, b) => a + b, 0) / 6) * 10) / 10;
            const criteria = {
                quality: data.quality,
                productivity: data.productivity,
                communication: data.communication,
                discipline: data.discipline,
                initiative: data.initiative,
                teamwork: data.teamwork,
            };
            const notes = JSON.stringify({
                period: data.period,
                rating_avg: rating,
                criteria, // all ratings are stored here
                strengths: data.strengths ?? '',
                development: data.development ?? '',
                goals: data.goals ?? '',
            });

            const body = {
                employee_id: Number(data.employee_id),
                reviewer_name: reviewToEdit?.reviewer_name?.trim() || 'موظف الموارد البشرية',
                rating,
                notes,
            };

            await apiPost({
                endpoint: reviewToEdit ? endpoints.review.update + reviewToEdit.id : endpoints.review.create,
                body,
            });

            toast.success(reviewToEdit ? 'تم تحديث التقييم بنجاح' : 'تم حفظ التقييم بنجاح', {
                className: 'font-cairo',
            });
            onSaved?.();
            onOpenChange(false);
        } catch (error: unknown) {
            const err = error as { message?: string; response?: { data?: { msg?: string; errors?: Record<string, string[]> } } };
            if (err.message && !err.response) {
                toast.error(err.message, { className: 'font-cairo' });
                return;
            }
            const msg =
                err.response?.data?.msg ||
                (err.response?.data?.errors &&
                    Object.values(err.response.data.errors)
                        .flat()
                        .join(' ')) ||
                'تعذر حفظ التقييم. حاول مرة أخرى.';
            toast.error(msg, { className: 'font-cairo' });
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent
                showCloseButton={false}
                dir="rtl"
                className="lg:max-w-[920px] max-w-[90%] max-h-[92vh] overflow-y-auto rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-0 border-[#E8E7EA]"
            >
                <DialogHeader className="flex flex-col items-stretch space-y-0">
                    <div className="flex flex-row items-center gap-2 mb-4">
                        <PlusIcon />
                        <h2 className="md:text-[22px] text-[18px] font-bold text-primery-blue-500">
                            {reviewToEdit ? 'تعديل تقييم الموظف' : 'معايير تقييم الموظف'}
                        </h2>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1]" />
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6 space-y-6">
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                            <div className="space-y-5 order-2 lg:order-1">
                                {CRITERIA.map((c) => (
                                    <FormField
                                        key={c.name}
                                        control={form.control}
                                        name={c.name}
                                        render={({ field }) => (
                                            <FormItem>
                                                <FormControl>
                                                    <StarCriterion
                                                        label={c.label}
                                                        value={field.value}
                                                        onChange={field.onChange}
                                                    />
                                                </FormControl>
                                                <FormMessage />
                                            </FormItem>
                                        )}
                                    />
                                ))}
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 order-1 lg:order-2">
                                <div className="sm:col-span-2">
                                    <SearchableSelectInputForm
                                        name="employee_id"
                                        label="اسم الموظف"
                                        placeholder={employeesLoading ? 'جاري تحميل الموظفين...' : 'اختر الموظف'}
                                        options={employeeOptions}
                                    />
                                </div>
                                <FormField
                                    control={form.control}
                                    name="period"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                                الفترة التقييمية
                                            </FormLabel>
                                            <Select onValueChange={field.onChange} value={field.value}>
                                                <FormControl>
                                                    <SelectTrigger className="relative ps-10 text-start">
                                                        <CalendarIcon
                                                            width="20"
                                                            height="20"
                                                            className="absolute start-3 top-1/2 -translate-y-1/2 text-primery-blue-400 pointer-events-none"
                                                        />
                                                        <SelectValue placeholder="اختر الفترة" />
                                                    </SelectTrigger>
                                                </FormControl>
                                                <SelectContent>
                                                    {periodOptions.map((p) => (
                                                        <SelectItem key={p.value} value={p.value}>
                                                            {p.label}
                                                        </SelectItem>
                                                    ))}
                                                </SelectContent>
                                            </Select>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                                <FormItem>
                                    <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                        المقيم
                                    </FormLabel>
                                    <FormControl>
                                        <input
                                            readOnly
                                            value={user?.name}
                                            className="w-full h-10 rounded-md bg-[#F3F4F6] border border-[#E5E7EB] px-3 cursor-default"
                                        />
                                    </FormControl>
                                </FormItem>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="strengths"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            نقاط القوة
                                        </FormLabel>
                                        <FormControl>
                                            <Textarea
                                                {...field}
                                                rows={4}
                                                placeholder="أذكر أبرز نقاط القوة لدى الموظف"
                                                className="placeholder:text-white-blue-600 min-h-[120px] resize-y"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <FormField
                                control={form.control}
                                name="development"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            مجالات التطوير
                                        </FormLabel>
                                        <FormControl>
                                            <Textarea
                                                {...field}
                                                rows={4}
                                                placeholder="أذكر النقاط التي تحتاج إلى تحسين"
                                                className="placeholder:text-white-blue-600 min-h-[120px] resize-y"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>

                        <FormField
                            control={form.control}
                            name="goals"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                        أهداف الفترة القادمة
                                    </FormLabel>
                                    <FormControl>
                                        <Textarea
                                            {...field}
                                            rows={3}
                                            placeholder="حدد الأهداف المقترحة"
                                            className="placeholder:text-white-blue-600 min-h-[100px] resize-y"
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <div className="mt-2 mb-6 text-[#6B7280] font-medium text-[14px] leading-[28px] tracking-normal">
                            <FileInput
                                name="review_file"
                                label="رفع ملف"
                                multiple={false}
                                maxSize={10 * 1024 * 1024}
                            />
                        </div>

                        <div className="flex flex-row-reverse gap-4 pt-2">
                            <PrimaryButton
                                type="submit"
                                disabled={submitting}
                                className="flex-1 text-base font-semibold py-3"
                            >
                                {submitting ? 'جاري الحفظ...' : reviewToEdit ? 'حفظ التغييرات' : 'اضافة'}
                            </PrimaryButton>
                            <SecondaryButton
                                type="button"
                                className="flex-1 text-base font-semibold py-3"
                                onClick={() => onOpenChange(false)}
                            >
                                إلغاء
                            </SecondaryButton>
                        </div>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}
