export type ReviewCriteria = {
    quality?: number;
    productivity?: number;
    communication?: number;
    discipline?: number;
    initiative?: number;
    teamwork?: number;
};

export type ParsedReviewNotes = {
    period?: string;
    rating_avg?: number;
    criteria?: ReviewCriteria;
    strengths?: string;
    development?: string;
    goals?: string;
    /** Present when `notes` is not valid JSON */
    rawText?: string;
};

export function parseReviewNotes(notes: string | null | undefined): ParsedReviewNotes {
    if (notes == null || !String(notes).trim()) {
        return {};
    }
    const s = String(notes).trim();
    if (!s.startsWith('{')) {
        return { rawText: s };
    }
    try {
        const o = JSON.parse(s) as Record<string, unknown>;
        const criteria = o.criteria;
        return {
            period: typeof o.period === 'string' ? o.period : undefined,
            rating_avg: typeof o.rating_avg === 'number' ? o.rating_avg : undefined,
            criteria:
                criteria && typeof criteria === 'object' && !Array.isArray(criteria)
                    ? (criteria as ReviewCriteria)
                    : undefined,
            strengths: typeof o.strengths === 'string' ? o.strengths : undefined,
            development: typeof o.development === 'string' ? o.development : undefined,
            goals: typeof o.goals === 'string' ? o.goals : undefined,
        };
    } catch {
        return { rawText: s };
    }
}
