import { ColumnDef, Row } from '@tanstack/react-table';
import { useState } from 'react';
import { format } from 'date-fns';
import EditIcon from '@/components/icons/EditIcon';
import ViewIcon from '@/components/icons/ViewIcon';
import TrashIcon from '@/components/icons/TrashIcon';
import { EmployeeReview } from '@/types/employee.types';
import { endpoints } from '@/lib/axios/axios-global';
import DeletePopup from '@/components/Popups/DeletePopup';
import { toast } from 'sonner';
import ReviewViewDialog from './ReviewViewDialog';
import AddEmployeeReviewDialog from './AddEmployeeReviewDialog';

function formatReviewDate(iso: string | undefined): string {
    if (!iso) return '—';
    try {
        return format(new Date(iso), 'yyyy-MM-dd');
    } catch {
        return iso;
    }
}

const ActionsCell = ({ row }: { row: Row<EmployeeReview> }) => {
    const [viewOpen, setViewOpen] = useState(false);
    const [editOpen, setEditOpen] = useState(false);
    const [deleteOpen, setDeleteOpen] = useState(false);
    const refresh = row.original.refreshTable;

    return (
        <>
            <ReviewViewDialog open={viewOpen} onOpenChange={setViewOpen} review={row.original} />
            <AddEmployeeReviewDialog
                key={row.original.id}
                open={editOpen}
                onOpenChange={setEditOpen}
                onSaved={() => {
                    refresh?.();
                    setEditOpen(false);
                }}
                reviewToEdit={editOpen ? row.original : null}
            />
            <DeletePopup
                open={deleteOpen}
                endpoint={endpoints.review.delete + row.original.id}
                text="هل أنت متأكد من حذف هذا التقييم؟ لا يمكن التراجع عن هذا الإجراء."
                handleCancel={() => setDeleteOpen(false)}
                handleSuccess={() => {
                    setDeleteOpen(false);
                    toast.success('تم حذف التقييم', { className: 'font-cairo' });
                    refresh?.();
                }}
            />
            <div className="me-6 text-end flex flex-row items-center justify-end gap-4">
                <button
                    type="button"
                    onClick={() => setViewOpen(true)}
                    className="hover:bg-white-blue-300 rounded-full p-1"
                    aria-label="عرض التفاصيل"
                >
                    <ViewIcon className="text-primery-blue-400" />
                </button>
                <button
                    type="button"
                    onClick={() => setEditOpen(true)}
                    className="hover:bg-white-blue-300 rounded-full p-1"
                    aria-label="تعديل التقييم"
                >
                    <EditIcon className="text-primery-blue-400" />
                </button>
                <button
                    type="button"
                    onClick={() => setDeleteOpen(true)}
                    className="hover:bg-white-blue-300 rounded-full p-1"
                    aria-label="حذف التقييم"
                >
                    <TrashIcon className="text-[#E81E1E] cursor-pointer" />
                </button>
            </div>
        </>
    );
};

export const columns: ColumnDef<EmployeeReview>[] = [
    {
        accessorKey: 'employee',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                اسم الموظف
            </div>
        ),
        cell: ({ row }) => {
            const emp = row.original.employee;
            return (
                <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    <div className="flex flex-col gap-1">
                        <p className="tracking-normal text-primery-blue-900 font-medium text-sm">{emp?.name ?? '—'}</p>
                        {emp?.email ? (
                            <p className="tracking-normal text-white-blue-800 font-normal text-xs">{emp.email}</p>
                        ) : null}
                    </div>
                </div>
            );
        },
    },
    {
        accessorKey: 'created_at',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                تاريخ التقييم
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-[#625E74] leading-[26.24px] font-semibold tracking-normal tabular-nums">
                {formatReviewDate(row.original.created_at)}
            </div>
        ),
    },
    {
        accessorKey: 'rating',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                متوسط التقييم
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] tabular-nums px-4 py-3">
                {row.original.rating != null ? `${row.original.rating} / 5` : '—'}
            </div>
        ),
    },
    {
        accessorKey: 'reviewer_name',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                المقيم
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {row.original.reviewer_name ?? '—'}
            </div>
        ),
    },
    {
        id: 'actions',
        header: () => (
            <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                إجراءات
            </div>
        ),
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
